from .core import *

def make(family,v,n):
    a=3+v;b=5+v
    if family=='review':
        tasks=[expr(f'На столе {a} карандаша, добавили {b}. Сколько стало?',a,b,'+','При добавлении складываем.',equation(f'{a} + {b}')),
          expr(f'Было {a+b} тетрадей, раздали {a}. Сколько осталось?',a+b,a,'−','При удалении вычитаем.'),
          expr(f'В {a} наборах по 4 фломастера. Сколько всего?',a,4,'×','Одинаковые группы удобно считать умножением.'),
          expr(f'{a*4} фломастеров разделили поровну на 4 набора. Сколько в одном?',a*4,4,'÷','При делении поровну находим размер одной группы.'),
          order('Расположи числа от меньшего к большему.',[34+v,8+v,21+v],'Сначала сравни число цифр, затем разряды.'),
          number(f'Прямоугольник: длина {a} см, ширина 2 см. Найди периметр в см.',2*(a+2),'Периметр — сумма длин всех сторон.',check={'op':'×','args':['2',str(a+2)]})]
        return package('Разминка перед путешествием',['Сложение объединяет, вычитание находит остаток.','Умножение заменяет сумму одинаковых слагаемых. Периметр — длина границы.'],['3 набора по 4 карандаша','3 × 4 = 12 карандашей.'], 'Придумай задачу на два действия и объясни порядок решения.',tasks)
    if family=='compare':
        x=3+v;y=x+4
        tasks=[choice(f'Какая точка правее: A({x}) или B({y})?',f'B({y})',[f'A({x})',f'B({y})'],'На луче координаты растут вправо.',model={'type':'ray','max':10,'points':[[x,'A'],[y,'B']]}),
          choice(f'{20+x} … {20+y}. Выбери знак.','<',['>','<','='],'При одинаковых десятках сравни единицы.'),
          choice(f'{50+x} … {50+x}. Выбери знак.','=',['<','=','>'],'Одинаковые числа равны.'),
          order('Расставь результаты команд по возрастанию.',[12+v,30+v,7+v,21+v],'Нажимай сначала на самое маленькое число.'),
          choice(f'Как записать: {x} меньше {x+2}, а {x+2} меньше {y}?',f'{x} < {x+2} < {y}',[f'{x} < {x+2} < {y}',f'{x} > {x+2} > {y}',f'{x} = {x+2} = {y}'],'В двойном неравенстве нужно проверить обе части.'),
          number(f'Сколько натуральных чисел строго между {x} и {y}?',y-x-1,'Крайние числа не включаются. Выпиши промежуточные числа.')]
        return package('Парад чисел',['На координатном луче большее число расположено правее.','Знаки < и > направлены остриём к меньшему числу.'],['Сравни 14, 9 и 20','9 < 14 < 20: обе части двойного неравенства верны.'],'Отметь на луче три числа и запиши двойное неравенство.',tasks)
    if family=='arithmetic':
        tasks=[choice('Что выполняют первым в 3 + 2 × 4?','Умножение',['Сложение','Умножение'],'Без скобок сначала умножение и деление.'),
          number(f'{a} + 2 × 4 = ?',a+8,'Умножь 2 на 4, затем прибавь первое число.'),
          number(f'({a} + 2) × 4 = ?',(a+2)*4,'Сначала выполни действие в скобках.'),
          number(f'25 + {a} + 75 = ?',100+a,'Переставь слагаемые: 25 + 75 = 100.'),
          number(f'4 × ({a} + 5) = ?',4*(a+5),'Можно умножить 4 на каждое слагаемое и сложить результаты.'),
          number(f'20 − 8 ÷ 2 + 3 × 4 − {a} + 1 = ?',29-a,'Здесь шесть действий. Сначала деление и умножение, затем слева направо.')]
        return package('Мастерская действий',['Скобки меняют порядок действий.','Переместительное, сочетательное и распределительное свойства помогают считать удобно.'],['6 × (10 + 2)','6 × 10 + 6 × 2 = 72.'],'Составь выражение более чем с четырьмя действиями и объясни порядок.',tasks)
    if family in ['simplify','substitute']:
        if family=='simplify':
            tasks=[choice(f'{a}a + 2a = ?',f'{a+2}a',[f'{a+2}a',f'{a*2}a',f'{a+2}'],'Складывай коэффициенты одинаковой буквы.'),
              choice('a + a + a = ?','3a',['a³','3a','3'],'Буквенное выражение 3a означает 3 × a.'),
              choice(f'{a}(x + 2) = ?',f'{a}x + {2*a}',[f'{a}x + {2*a}',f'{a}x + 2',f'x + {2*a}'],'Умножь число перед скобкой на каждое слагаемое.'),
              choice(f'{a+4}b − 4b = ?',f'{a}b',[f'{a}b',f'{a+8}b','4'],'Вычти коэффициенты.'),
              number(f'После упрощения {a}x + x получим kx. Чему равно k?',a+1,'Перед одиночной буквой стоит коэффициент 1.'),
              choice(f'Как упростить 2(y + {a}) + y?',f'3y + {2*a}',[f'3y + {2*a}',f'2y + {a}',f'3y + {a}'],'Раскрой скобки, затем объедини одинаковые буквы.')]
        else:
            tasks=[number(f'a = {a}. Найди a + 5.',a+5,'Вместо буквы подставь данное число.'),number(f'x = {a}. Найди 3x.',3*a,'3x означает 3 × x.'),number(f'b = {b}. Найди 2b − 3.',2*b-3,'Сначала подставь число, затем умножь.'),number(f'a = 2, b = {b}. Найди a + 2b.',2+2*b,'Каждую букву замени её значением.'),number(f'x = {a}. Найди 2(x + 4).',2*(a+4),'Сначала найди значение в скобках.'),number(f'Блокнот стоит c тенге. c = {100+v*20}. Сколько стоят 3 блокнота?',3*(100+v*20),'Модель стоимости: 3c. Цены учебные.')]
        return package('Буквы вместо чисел',['Буква обозначает число, которое может меняться.','При подстановке сохраняй знаки действий и скобки.'],['3a + 2a при a = 4','3a + 2a = 5a; 5 × 4 = 20.'],'Придумай выражение с буквой и вычисли его при двух значениях.',tasks)
    if family in ['equations','check_equations']:
        tasks=[number(f'x + {a} = {a+b}. Найди x.',b,'Чтобы найти слагаемое, из суммы вычти известное слагаемое.'),number(f'x − {a} = {b}. Найди x.',a+b,'Неизвестное уменьшаемое: разность плюс вычитаемое.'),number(f'{a+b} − x = {a}. Найди x.',b,'Неизвестное вычитаемое: уменьшаемое минус разность.'),number(f'{a}x = {a*4}. Найди x.',4,'Неизвестный множитель находят делением.'),choice(f'Для x + {a} = {a+b} предложили x = {b+1}. Это корень?','Нет',['Да','Нет'],'Подставь предложенное число: левая и правая части должны совпасть.'),number(f'{a*5} ÷ x = 5. Найди и проверь x.',a,'Неизвестный делитель: делимое разделить на частное.')]
        if family=='check_equations':
            tasks[0]=choice(f'Подходит ли x = {b} к уравнению 2x + 1 = {2*b+1}?','Да',['Нет','Да'],'Корень превращает уравнение в верное равенство.')
            tasks[3]=number(f'Проверь x = {a} для 4x = {a*4}: чему равна левая часть?',4*a,'Подставь x в левую часть, затем сравни обе части.')
        return package('Детектив неизвестного',['Уравнение содержит неизвестное число.','Корень проверяют подстановкой в исходное уравнение.'],['x + 7 = 15','x = 15 − 7 = 8. Проверка: 8 + 7 = 15.'],'Составь уравнение, реши его и отдельно запиши проверку.',tasks)
    if family=='formulas':
        tasks=[number(f'Стороны прямоугольника {a} см и 2 см. Найди P = 2(a + b).',2*(a+2),'Подставь длины сторон в формулу периметра.'),number(f'Найди площадь прямоугольника {a} см × {b} см.',a*b,'S = a × b. Ответ получится в квадратных сантиметрах.'),number(f'Велосипедист едет {a+7} км/ч в течение 2 ч. Какой путь в км?',2*(a+7),'s = v × t. Скорость считаем постоянной.'),choice('Цена одной тетради c тенге. Как выразить стоимость 5 тетрадей?','5c',['c + 5','5c','c ÷ 5'],'Стоимость равна цене, умноженной на количество.'),number(f'За 4 одинаковых набора заплатили {4*(120+20*v)} тг. Цена набора?',120+20*v,'Стоимость раздели на количество. Цены учебные.'),number(f'Для кружка взяли 3 набора по {a} деталей и ещё 5 деталей. Сколько всего?',3*a+5,'Сначала найди число деталей в наборах, потом добавь остальные.')]
        return package('Формулы в деле',['Формула связывает величины: P = 2(a + b), S = ab, s = vt.','Перед вычислением проверь единицы величин.'],['v = 12 км/ч, t = 2 ч','s = 12 × 2 = 24 км.'],'Составь задачу по формуле стоимости и укажи единицы.',tasks)
    if family in ['sequences','invent_sequences']:
        start=2+v;step=3+v
        tasks=[number(f'Продолжи: {start}, {start+step}, {start+2*step}, …',start+3*step,'Сравни соседние числа: на сколько они увеличиваются?'),number(f'Заполни пропуск: {2*step}, {3*step}, …, {5*step}.',4*step,'Сохраняй один и тот же шаг.'),number(f'Продолжи: {a}, {2*a}, {4*a}, …',8*a,'Каждое следующее число в 2 раза больше.'),choice('Правило: прибавлять 4. Какая цепочка подходит?','3, 7, 11, 15',['3, 7, 11, 15','3, 6, 9, 12','3, 7, 12, 16'],'Проверь переход между каждой парой соседних чисел.'),number(f'Начни с {start}, трижды прибавь {step}. Какое число получится?',start+3*step,'Три прибавления — это три перехода.'),dict(type='sequence',prompt='Придумай своё правило: начни с 2 и каждый раз прибавляй одно и то же натуральное число.',answer=None,start=2,count=4,note='Введи четыре следующих числа через пробел. Шаг выбери сам.',hint='Например, можно каждый раз прибавлять 3. Сохрани выбранное правило.',success='В твоей последовательности сохраняется выбранный шаг!')]
        return package('Лаборатория закономерностей',['Проверь правило на всех соседних членах, а не только на первых двух.','У придуманной последовательности нужно сформулировать правило.'],['2, 5, 8, 11','Каждый раз прибавляем 3. Следующее число — 14.'],'Придумай две разные последовательности и дай однокласснику восстановить правила.',tasks)
    raise ValueError(family)
